/**
 * Compresses a single file buffer in place.
 * Updates msg.payload with compressed buffer and msg._file_meta with new metadata.
 * On failure, sets msg.payload to null so Store file marks it as failed.
 */
const utils = global.get("utils");
const meta = msg._file_meta;
const buffer = msg.payload;
const target_attr = utils.get_system_attributes(msg.metadata.target.client_system);
const TARGET_SIZE = target_attr.max_upload_bytes;

// Not compressible — can't reduce size, fail
if (!utils.is_compressible(meta.type)) {
    node.warn("[COMPRESS] Not compressible: " + meta.name);
    msg.payload = null;
    return msg;
}

const isImage = meta.type.startsWith("image/");
const isVideo = meta.type.startsWith("video/");

// --- IMAGE: compress with sharp ---
if (isImage) {
    try {
        let quality = 80;
        let compressed = await sharp(buffer).rotate().jpeg({ quality }).toBuffer();

        while (compressed.length > TARGET_SIZE && quality > 10) {
            quality -= 10;
            compressed = await sharp(buffer).rotate().jpeg({ quality }).toBuffer();
        }

        if (compressed.length <= TARGET_SIZE) {
            msg.payload = compressed;
            msg._file_meta.name = meta.name.replace(/\.[^.]+$/, "") + ".jpg";
            msg._file_meta.type = "image/jpeg";
            msg._file_meta.size = compressed.length;
            node.warn("[SHARP] " + meta.name + ": " + buffer.length + " → " + compressed.length + " bytes (quality: " + quality + ")");
        } else {
            node.warn("[SHARP] Could not compress " + meta.name + " under target");
            msg.payload = null;
        }
    } catch (e) {
        node.warn("[SHARP] Error: " + e.message);
        msg.payload = null;
    }
    return msg;
}

// --- VIDEO/AUDIO: compress with ffmpeg via stdin/stdout ---

// Helper: spawn process, pipe buffer to stdin, collect stdout
const run = (cmd, args) => new Promise((resolve, reject) => {
    const proc = childProcess.spawn(cmd, args);
    const chunks = [];
    let stderr = "";

    proc.stdout.on("data", chunk => chunks.push(chunk));
    proc.stderr.on("data", chunk => { stderr += chunk; });
    proc.on("close", code => {
        if (code !== 0) return reject(new Error(stderr || "exit code " + code));
        resolve(Buffer.concat(chunks));
    });
    proc.on("error", reject);

    proc.stdin.write(buffer);
    proc.stdin.end();
});

try {
    // Get duration via ffprobe from stdin
    const probeOut = await run("ffprobe", [
        "-v", "error",
        "-show_entries", "format=duration",
        "-of", "default=noprint_wrappers=1:nokey=1",
        "pipe:0"
    ]);
    const duration = parseFloat(probeOut.toString());
    if (isNaN(duration) || duration <= 0) throw new Error("Invalid duration");

    const targetBytes = TARGET_SIZE - (32 * 1024);
    const audioBitrate = 64000;
    const totalBitrate = Math.floor((targetBytes * 8) / duration);
    const videoBitrate = Math.max(totalBitrate - audioBitrate, 50000);

    const args = ["-i", "pipe:0", "-y"];

    if (isVideo) {
        args.push(
            "-vcodec", "libx264",
            "-b:v", videoBitrate + "",
            "-maxrate", videoBitrate + "",
            "-bufsize", Math.floor(videoBitrate / 2) + "",
            "-preset", "fast",
            "-vf", "scale=min(640\\,iw):min(480\\,ih):force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2",
            "-acodec", "aac",
            "-b:a", "64k",
            "-movflags", "frag_keyframe+empty_moov",
            "-f", "mp4"
        );
    } else {
        const audioBr = Math.min(Math.floor(totalBitrate), 128000);
        args.push("-acodec", "aac", "-b:a", audioBr + "", "-f", "adts");
    }

    args.push("pipe:1");

    const compressed = await run("ffmpeg", args);

    node.warn("[FFMPEG] " + meta.name + ": " + buffer.length + " → " + compressed.length + " bytes (duration: " + duration.toFixed(1) + "s)");

    msg.payload = compressed;
    if (isVideo) {
        msg._file_meta.name = meta.name.replace(/\.[^.]+$/, "") + ".mp4";
        msg._file_meta.type = "video/mp4";
    }
    msg._file_meta.size = compressed.length;
} catch (e) {
    node.warn("[FFMPEG] Failed for " + meta.name + ": " + e.message);
    msg.payload = null;
}

return msg;
